package dev.bedrockvisuals.bedrock;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

/**
 * Java block texture name to Bedrock texture path, generated by tools/gen_texture_map.py and hand-fixed in
 * tools/texture_map_overrides.json.
 */
public final class TextureMap {
	private static final String RESOURCE = "/bedrockvisuals/texture_map.json";

	private final Map<String, String> javaToBedrock;

	private TextureMap(Map<String, String> javaToBedrock) {
		this.javaToBedrock = javaToBedrock;
	}

	public static TextureMap load() {
		try (InputStream in = TextureMap.class.getResourceAsStream(RESOURCE)) {
			if (in == null) {
				throw new IllegalStateException(RESOURCE + " is missing from the mod jar");
			}
			JsonObject json = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
			Map<String, String> map = new HashMap<>();
			json.entrySet().forEach(e -> map.put(e.getKey(), e.getValue().getAsString()));
			return new TextureMap(Map.copyOf(map));
		} catch (IOException e) {
			throw new UncheckedIOException(e);
		}
	}

	/** Every mapped Java block texture name. */
	public java.util.Set<String> javaTextures() {
		return javaToBedrock.keySet();
	}

	public int size() {
		return javaToBedrock.size();
	}

	/** @param javaTexture a block texture name as in assets/minecraft/textures/block, e.g. "oak_log" */
	public Optional<TextureSet> textureSetFor(BedrockPack pack, String javaTexture) {
		String bedrock = javaToBedrock.get(javaTexture);
		return bedrock == null ? Optional.empty() : pack.textureSet("blocks/" + bedrock);
	}
}
